{"id": "framing-what-is-found", "name": "What Frame Job finds in the picture", "summary": "Frame Job finds who and what is in a clip's picture on this Mac with Apple's Vision framework, with nothing uploaded and no key needed.", "page": "framing/what-is-found", "anchor": "what-is-found", "where": "Clip ▸ Follow Subject…"}
{"id": "framing-found-people", "name": "People", "summary": "Each person's head and shoulders, as a box.", "page": "framing/what-is-found", "anchor": "people", "where": "View ▸ Show Subjects"}
{"id": "framing-boxes-no-identity", "name": "Boxes, not people", "summary": "Boxes are found in each sample on its own: Frame Job does not follow a person from one moment to the next or put names to faces.", "page": "framing/what-is-found", "anchor": "boxes-not-people"}
{"id": "show-subjects", "name": "Show Subjects", "summary": "Draws what has been found for the selected clip at the playhead over the preview.", "page": "framing/show-subjects", "anchor": "turn-on-show-subjects", "where": "View ▸ Show Subjects"}
{"id": "show-subjects-outlines", "name": "What the outlines mean", "summary": "Faces are outlined in yellow, people in teal and salient regions in purple with a dashed line.", "page": "framing/show-subjects", "anchor": "what-the-outlines-mean", "where": "View ▸ Show Subjects"}
{"id": "show-subjects-follows-clip", "name": "The boxes stay on the picture", "summary": "The boxes sit on the clip's picture wherever it is placed, and follow its speed, speed ramps and reversal.", "page": "framing/show-subjects", "anchor": "the-boxes-stay-on-the-picture", "where": "View ▸ Show Subjects"}
{"id": "show-subjects-not-analyzed", "name": "Not analyzed", "summary": "When nothing has been found for the clip's picture at the playhead, the preview says so at the clip's top-left corner.", "page": "framing/show-subjects", "anchor": "not-analyzed", "where": "View ▸ Show Subjects"}
{"id": "show-subjects-per-window", "name": "A view of the window", "summary": "Show Subjects is off in a new window, is not remembered between launches, and never changes an export or a saved frame.", "page": "framing/show-subjects", "anchor": "a-view-of-the-window", "where": "View ▸ Show Subjects"}
{"id": "follow-subject", "name": "Follow Subject", "summary": "Frames each selected movie clip on its subject with eased moves on its action lane, on the current canvas.", "page": "framing/follow-subject", "anchor": "frame-clips-on-their-subject", "where": "Clip ▸ Follow Subject…"}
{"id": "follow-subject-follow", "name": "Follow", "summary": "Chooses what the frame follows.", "page": "framing/follow-subject", "anchor": "follow", "where": "Clip ▸ Follow Subject… ▸ Follow"}
{"id": "follow-subject-zoom", "name": "Zoom", "summary": "Sets how tight the frame is, 100 to 400 %.", "page": "framing/follow-subject", "anchor": "zoom", "where": "Clip ▸ Follow Subject… ▸ Zoom"}
{"id": "follow-subject-where-empty", "name": "Where Empty", "summary": "Sets what the frame shows while there is nothing to follow.", "page": "framing/follow-subject", "anchor": "where-empty", "where": "Clip ▸ Follow Subject… ▸ Where Empty"}
{"id": "follow-subject-summary", "name": "The summary", "summary": "Under the controls, the sheet says what Follow will do before you press it.", "page": "framing/follow-subject", "anchor": "the-summary", "where": "Clip ▸ Follow Subject…"}
{"id": "follow-subject-analysis-first", "name": "Analysis first", "summary": "When the clips have not been analysed, Follow shows the Analyzing sheet while faces, people and shot changes are found on this Mac, then frames the clips.", "page": "framing/follow-subject", "anchor": "analysis-first", "where": "Clip ▸ Follow Subject… ▸ Follow ▸ Analyzing sheet"}
{"id": "follow-subject-replaces-placement", "name": "It starts from the whole picture", "summary": "Each clip is framed from the whole picture: its own positions and scales, in its base and its actions, are replaced, and its volume and other actions stay.", "page": "framing/follow-subject", "anchor": "it-starts-from-the-whole-picture", "where": "Clip ▸ Follow Subject…"}
{"id": "framing-eases-and-stays-put", "name": "How following moves: easing", "summary": "The frame eases onto the subject and moves only when the subject leaves the middle of the frame, so a speaker who sways stays put.", "page": "framing/follow-subject", "anchor": "easing-and-staying-put", "where": "Clip ▸ Follow Subject…"}
{"id": "framing-cuts-at-shots", "name": "How following moves: cuts", "summary": "The frame cuts with the picture at each shot change, landing on the first frame of the new shot.", "page": "framing/follow-subject", "anchor": "at-a-shot-change", "where": "Clip ▸ Follow Subject…"}
{"id": "framing-holds-when-lost", "name": "How following moves: a lost subject", "summary": "The frame holds for a second when the subject is lost, so a blink or a turned head changes nothing, then follows someone else in the shot or eases away.", "page": "framing/follow-subject", "anchor": "when-the-subject-is-lost", "where": "Clip ▸ Follow Subject…"}
{"id": "framing-returns-to-subject", "name": "How following moves: coming back", "summary": "The frame comes back once a subject has been in view for 0.6 s.", "page": "framing/follow-subject", "anchor": "when-the-subject-is-lost", "where": "Clip ▸ Follow Subject…"}
{"id": "framing-two-people", "name": "How following moves: two people", "summary": "The frame holds two people together when both fit in it.", "page": "framing/follow-subject", "anchor": "two-people", "where": "Clip ▸ Follow Subject…"}
{"id": "framing-backgrounds-track", "name": "The blurred Backgrounds track", "summary": "Where the frame shows the whole picture, a blurred copy of the clip goes on a new Backgrounds track at the back, so the canvas around it is not empty.", "page": "framing/follow-subject", "anchor": "the-blurred-backgrounds-track", "where": "Clip ▸ Follow Subject…"}
{"id": "follow-subject-moves-editable", "name": "Every move is an action", "summary": "Every move is an ordinary action on the clip's action lane: select one and drag the picture on the canvas to nudge where its frame ends.", "page": "framing/follow-subject", "anchor": "every-move-is-an-action", "where": "Action lane"}
{"id": "follow-subject-undo", "name": "Undo Follow Subject", "summary": "Edit ▸ Undo Follow Subject takes the whole command back in one step.", "page": "framing/follow-subject", "anchor": "undo", "where": "Edit ▸ Undo Follow Subject"}
{"id": "follow-subject-skips-cursor-recordings", "name": "Screen recordings are skipped", "summary": "A screen recording Frame Job made, with its cursor file, is not followed by faces: it is left unanalysed and listed under the summary with the reason.", "page": "framing/follow-subject", "anchor": "screen-recordings-are-skipped", "where": "Clip ▸ Follow Subject…"}
{"id": "follow-subject-refusals", "name": "Clips it cannot frame", "summary": "A selected movie clip that cannot be followed is listed under the summary with the reason, and the others are still framed.", "page": "framing/follow-subject", "anchor": "clips-it-cannot-frame", "where": "Clip ▸ Follow Subject… ▸ summary"}
{"id": "make-vertical-version", "name": "Make Vertical Version", "summary": "Makes a tall or square version of a landscape edit, for a phone, a reel or a square post, from the whole timeline in one step.", "page": "framing/make-vertical-version", "anchor": "make-a-vertical-version", "where": "File ▸ Make Vertical Version…"}
{"id": "make-vertical-shape", "name": "Shape", "summary": "Picks 9:16, 4:5 or 1:1, each shown with the size it makes.", "page": "framing/make-vertical-version", "anchor": "shape", "where": "File ▸ Make Vertical Version… ▸ Shape"}
{"id": "make-vertical-follow", "name": "Follow", "summary": "Chooses what each movie clip follows, as in Follow Subject, with one more choice, Speaker.", "page": "framing/make-vertical-version", "anchor": "follow", "where": "File ▸ Make Vertical Version… ▸ Follow"}
{"id": "make-vertical-zoom", "name": "Zoom", "summary": "Sets how tight the frame is, 100 to 400 % of the scale at which a picture just covers the new canvas.", "page": "framing/make-vertical-version", "anchor": "zoom", "where": "File ▸ Make Vertical Version… ▸ Zoom"}
{"id": "make-vertical-where-empty", "name": "Where Empty", "summary": "Sets what a followed clip shows while there is nothing to follow, as in Follow Subject.", "page": "framing/make-vertical-version", "anchor": "where-empty", "where": "File ▸ Make Vertical Version… ▸ Where Empty"}
{"id": "make-vertical-copy", "name": "Make a copy", "summary": "Opens the vertical version as a new untitled project and leaves this one unchanged, or, unticked, turns this project itself into the vertical version.", "page": "framing/make-vertical-version", "anchor": "make-a-copy", "where": "File ▸ Make Vertical Version… ▸ Make a copy"}
{"id": "make-vertical-summary", "name": "The summary", "summary": "Under the controls, the sheet says what Make will do before you press it.", "page": "framing/make-vertical-version", "anchor": "read-the-summary", "where": "File ▸ Make Vertical Version…"}
{"id": "make-vertical-analysis-first", "name": "Analysis first", "summary": "When the movies have not been analysed, Make shows the Analyzing sheet while faces, people and shot changes are found on this Mac, then makes the version.", "page": "framing/make-vertical-version", "anchor": "when-the-movies-need-analysing", "where": "File ▸ Make Vertical Version… ▸ Make ▸ Analyzing sheet"}
{"id": "make-vertical-analysis-carried", "name": "Making another shape", "summary": "What was found is kept in this project's cache and carried into the copy, so making another shape afterwards needs no analysis.", "page": "framing/make-vertical-version", "anchor": "make-another-shape", "where": "File ▸ Make Vertical Version…"}
{"id": "make-vertical-undo", "name": "Undo Make Vertical", "summary": "The whole change is one undo step: in the copy, Edit ▸ Undo Make Vertical gives back the landscape edit; in place, it takes the command back on this project.", "page": "framing/make-vertical-version", "anchor": "undo-make-vertical", "where": "Edit ▸ Undo Make Vertical"}
{"id": "make-vertical-sharpness", "name": "Sharpness", "summary": "A vertical canvas shows the middle of a landscape picture enlarged, so shoot 4K for footage you mean to make vertical.", "page": "framing/make-vertical-version", "anchor": "keep-the-picture-sharp", "where": "File ▸ Make Vertical Version…"}
{"id": "vertical-clip-classes", "name": "How a clip is judged", "summary": "Each clip with a picture on the top-level timeline is treated by what it is, judged on the old canvas.", "page": "framing/vertical-what-changes", "anchor": "how-a-clip-is-judged", "where": "File ▸ Make Vertical Version…"}
{"id": "vertical-movies-follow", "name": "Full-frame movies follow their subject", "summary": "A movie clip that fills the old frame on one side, the usual full-frame shot or one punched in a little, follows its subject as Follow Subject frames it, with its own moves and actions kept inside the framing.", "page": "framing/vertical-what-changes", "anchor": "full-frame-movies", "where": "File ▸ Make Vertical Version…"}
{"id": "vertical-blurred-copy", "name": "A blurred copy behind", "summary": "Where the frame shows the whole picture, a blurred copy of the clip goes behind it on a new Backgrounds track at the back.", "page": "framing/vertical-what-changes", "anchor": "full-frame-movies", "where": "File ▸ Make Vertical Version…"}
{"id": "vertical-screen-recordings", "name": "Screen recordings follow the pointer", "summary": "A screen recording with its cursor file follows the pointer instead of a face.", "page": "framing/vertical-what-changes", "anchor": "screen-recordings", "where": "File ▸ Make Vertical Version…"}
{"id": "vertical-camera-layouts", "name": "Camera layouts are re-laid", "summary": "A screen recording and its camera in camera layouts keep their arrangement: each switch is made again for the new canvas, at the same time, length and curve.", "page": "framing/vertical-what-changes", "anchor": "camera-layouts", "where": "File ▸ Make Vertical Version…"}
{"id": "vertical-hand-edited-layouts", "name": "A layout changed by hand", "summary": "When a camera was moved or resized after its switch, so it is no longer a layout Frame Job made, the camera and its screen are kept as placed and the summary says so.", "page": "framing/vertical-what-changes", "anchor": "a-layout-changed-by-hand", "where": "File ▸ Make Vertical Version…"}
{"id": "vertical-stills-nests-centred", "name": "Stills, pictures and nests are centred", "summary": "A still or a picture that fills the frame, and a nest that does, is centred.", "page": "framing/vertical-what-changes", "anchor": "stills-pictures-and-nests", "where": "File ▸ Make Vertical Version…"}
{"id": "vertical-kept-as-placed", "name": "Everything else is kept as placed", "summary": "Titles, other graphics, shapes and a picture-in-picture are moved and scaled from the old canvas to the new one, as the Document tab's canvas change does when it rescales clips.", "page": "framing/vertical-what-changes", "anchor": "everything-else", "where": "File ▸ Make Vertical Version…"}
{"id": "vertical-blurred-copies-plates", "name": "Blurred copies and background plates", "summary": "A blurred copy already behind a clip is removed when that clip now follows its subject, and otherwise re-filled to cover the new canvas; a background plate is re-filled too.", "page": "framing/vertical-what-changes", "anchor": "blurred-copies-and-background-plates", "where": "File ▸ Make Vertical Version…"}
{"id": "vertical-captions-repaged", "name": "Word captions are re-paged", "summary": "Word captions are re-paged for the narrow frame from the words their pages hold, every correction kept, as File ▸ Re-lay Captions for This Canvas does.", "page": "framing/vertical-what-changes", "anchor": "word-captions", "where": "File ▸ Make Vertical Version…"}
{"id": "vertical-follow-speaker", "name": "Follow Speaker", "summary": "With Follow on Speaker, a wide shot of two to four people that plays beside their microphones cuts to whoever is talking.", "page": "framing/follow-speaker", "anchor": "how-the-shot-is-cut", "where": "File ▸ Make Vertical Version… ▸ Follow ▸ Speaker"}
{"id": "vertical-speaker-microphones", "name": "Microphones", "summary": "A checkbox for each track holding a sound file: tick the ones that belong to the people in the shot, two to four.", "page": "framing/follow-speaker", "anchor": "microphones", "where": "File ▸ Make Vertical Version… ▸ Follow ▸ Speaker ▸ Microphones"}
{"id": "vertical-speaker-faces", "name": "Faces", "summary": "One row per ticked microphone, with a pop-up of the faces Frame Job found in the longest such shot.", "page": "framing/follow-speaker", "anchor": "faces", "where": "File ▸ Make Vertical Version… ▸ Follow ▸ Speaker ▸ Faces"}
{"id": "vertical-speaker-match", "name": "The automatic match", "summary": "Frame Job matches each microphone to the face whose mouth moves while it talks, and sets the pop-ups when the match is clear.", "page": "framing/follow-speaker", "anchor": "the-automatic-match", "where": "File ▸ Make Vertical Version… ▸ Follow ▸ Speaker ▸ Faces"}
{"id": "vertical-speaker-choose-a-face", "name": "Choose a face", "summary": "When the faces do not show who is whose, mouths too still or too small to read, each pop-up says Choose a face and you pick each microphone's face yourself.", "page": "framing/follow-speaker", "anchor": "choose-a-face", "where": "File ▸ Make Vertical Version… ▸ Follow ▸ Speaker ▸ Faces"}
{"id": "vertical-speaker-when-make", "name": "When Make is offered", "summary": "Make is offered once two to four microphones are ticked, a shot plays beside two of them and every ticked microphone has a face of its own.", "page": "framing/follow-speaker", "anchor": "when-make-is-offered", "where": "File ▸ Make Vertical Version…"}
{"id": "vertical-speaker-sheet-returns", "name": "The sheet comes back after analysis", "summary": "With Speaker the sheet comes back once the analysis is done, with your choices kept, so you can confirm who is on each microphone; nothing is made until you press Make there.", "page": "framing/follow-speaker", "anchor": "the-sheet-comes-back-after-analysis", "where": "File ▸ Make Vertical Version…"}
{"id": "camera-layout", "name": "Camera Layout", "summary": "A screen recording with a camera in front of it can switch between layouts as it plays: put the playhead where the switch should happen and choose one.", "page": "framing/camera-layouts", "anchor": "", "where": "Clip ▸ Camera Layout ▸"}
{"id": "camera-layout-corner", "name": "Corner", "summary": "The camera in a square-cornered box in the corner you choose, showing its whole picture.", "page": "framing/camera-layouts", "anchor": "corner", "where": "Clip ▸ Camera Layout ▸ Corner ▸ Bottom Right / Bottom Left / Top Right / Top Left"}
{"id": "camera-layout-rounded-corner", "name": "Rounded Corner", "summary": "The same corner box with rounded corners.", "page": "framing/camera-layouts", "anchor": "rounded-corner", "where": "Clip ▸ Camera Layout ▸ Rounded Corner ▸ Bottom Right / Bottom Left / Top Right / Top Left"}
{"id": "camera-layout-circle", "name": "Circle", "summary": "The largest square of the camera picture, cropped to a circle in the corner you choose.", "page": "framing/camera-layouts", "anchor": "circle", "where": "Clip ▸ Camera Layout ▸ Circle ▸ Bottom Right / Bottom Left / Top Right / Top Left"}
{"id": "camera-layout-side-by-side", "name": "Side by Side", "summary": "The screen fitted in the left two-thirds and the camera cropped to fill the right third.", "page": "framing/camera-layouts", "anchor": "side-by-side", "where": "Clip ▸ Camera Layout ▸ Side by Side"}
{"id": "camera-layout-stacked", "name": "Stacked", "summary": "The screen across the top and the camera cropped to fill the rest below it.", "page": "framing/camera-layouts", "anchor": "stacked", "where": "Clip ▸ Camera Layout ▸ Stacked"}
{"id": "camera-layout-camera-full", "name": "Camera Full", "summary": "The camera fills the canvas.", "page": "framing/camera-layouts", "anchor": "camera-full", "where": "Clip ▸ Camera Layout ▸ Camera Full"}
{"id": "camera-layout-screen-only", "name": "Screen Only", "summary": "The camera is hidden where it is and the screen fills the canvas.", "page": "framing/camera-layouts", "anchor": "screen-only", "where": "Clip ▸ Camera Layout ▸ Screen Only"}
{"id": "camera-layout-which-clips", "name": "Which clips it uses", "summary": "The camera and screen are worked out from the selection or the playhead.", "page": "framing/camera-layouts", "anchor": "which-clips", "where": "Clip ▸ Camera Layout ▸"}
{"id": "camera-layout-switch-easing", "name": "The switch", "summary": "A switch eases over half a second from the playhead, as a layout action on each clip that you can see on its action lane and retime like any other.", "page": "framing/camera-layouts", "anchor": "the-switch", "where": "Clip ▸ Camera Layout ▸"}
{"id": "camera-layout-holds", "name": "How far a layout reaches", "summary": "A layout holds until the next switch, so a camera cut into pieces stays in the corner.", "page": "framing/camera-layouts", "anchor": "how-far-a-layout-reaches", "where": "Clip ▸ Camera Layout ▸"}
{"id": "camera-layout-refusals", "name": "When a switch is refused", "summary": "A switch that cannot be made changes nothing, and names the clip at the inspector's foot.", "page": "framing/camera-layouts", "anchor": "when-a-switch-is-refused", "where": "Clip ▸ Camera Layout ▸"}
{"id": "layout-section", "name": "The Layout section", "summary": "With one clip of a video file selected, the Picture sub-tab offers the layout choices in a Layout section.", "page": "framing/layout-section", "anchor": "", "where": "Inspector ▸ Clip ▸ Picture ▸ Layout"}
{"id": "layout-section-layout", "name": "Layout", "summary": "Choose Corner, Side by Side, Stacked, Camera Full or Screen Only.", "page": "framing/layout-section", "anchor": "the-controls", "where": "Inspector ▸ Clip ▸ Picture ▸ Layout ▸ Layout"}
{"id": "layout-section-shape", "name": "Shape", "summary": "Choose Square, Rounded or Circle for a corner layout.", "page": "framing/layout-section", "anchor": "the-controls", "where": "Inspector ▸ Clip ▸ Picture ▸ Layout ▸ Shape"}
{"id": "layout-section-corner", "name": "Corner", "summary": "Choose which canvas corner the camera sits in.", "page": "framing/layout-section", "anchor": "the-controls", "where": "Inspector ▸ Clip ▸ Picture ▸ Layout ▸ Corner"}
{"id": "layout-section-duration", "name": "Duration", "summary": "Sets how long the switch takes.", "page": "framing/layout-section", "anchor": "the-controls", "where": "Inspector ▸ Clip ▸ Picture ▸ Layout ▸ Duration"}
{"id": "layout-section-switch-at-playhead", "name": "Switch at Playhead", "summary": "Does exactly what the menu does, with this clip as the camera and the clip behind it as the screen.", "page": "framing/layout-section", "anchor": "switch-at-playhead", "where": "Inspector ▸ Clip ▸ Picture ▸ Layout ▸ Switch at Playhead"}
{"id": "layout-crop-on-person", "name": "The crop centred on the person", "summary": "Circle, Side by Side and Stacked centre the camera's crop on the person when its person masks already exist for every frame it plays.", "page": "framing/layout-section", "anchor": "the-crop-centred-on-the-person", "where": "Clip ▸ Camera Layout ▸"}
{"id": "layout-meets-a-zoom", "name": "A layout meets a zoom", "summary": "A switch never fights a zoom: it is refused when a clip it would move holds a zoom or another moving action after the playhead.", "page": "framing/layout-section", "anchor": "a-layout-meets-a-zoom", "where": "Clip ▸ Camera Layout ▸"}
{"id": "layout-nest-offer", "name": "Lay out the clips in a nest?", "summary": "When nesting those clips would let a refused switch go ahead, a sheet offers to nest them first, so the layout moves the nest and the zooms keep playing inside it.", "page": "framing/layout-section", "anchor": "lay-out-the-clips-in-a-nest", "where": "Sheet: Lay out the clips in a nest?"}
{"id": "reframe-clip", "name": "reframe_clip", "summary": "An agent frames one clip on the current canvas, say a landscape recording on a 1080 × 1920 canvas, choosing what to follow with follow.", "page": "framing/reframe-clip", "anchor": "frame-a-clip", "where": "Clip ▸ Follow Subject…"}
{"id": "reframe-follow-subject", "name": "follow: subject", "summary": "Follows a face; where there is none, a person; where there is neither, a salient region.", "page": "framing/reframe-clip", "anchor": "subject"}
{"id": "reframe-follow-face-person-salient", "name": "follow: face, person, salient", "summary": "Follows only that kind.", "page": "framing/reframe-clip", "anchor": "face-person-and-salient", "where": "Clip ▸ Follow Subject… ▸ Follow"}
{"id": "reframe-follow-cursor", "name": "follow: cursor", "summary": "Follows a screen recording's recorded pointer, from its media's cursor file.", "page": "framing/reframe-clip", "anchor": "cursor", "where": "File ▸ Make Vertical Version…"}
{"id": "reframe-follow-speaker", "name": "follow: speaker", "summary": "Frames a wide shot of two to four people on whoever is talking, each with a microphone of their own named in mics.", "page": "framing/reframe-clip", "anchor": "speaker", "where": "File ▸ Make Vertical Version… ▸ Follow ▸ Speaker"}
{"id": "reframe-follow-center", "name": "follow: center", "summary": "Holds the frame on the middle of the picture for the whole clip.", "page": "framing/reframe-clip", "anchor": "center", "where": "Clip ▸ Follow Subject… ▸ Follow ▸ Center"}
{"id": "reframe-follow-fit", "name": "follow: fit", "summary": "Shows the whole picture for the whole clip, scaled to fit the canvas.", "page": "framing/reframe-clip", "anchor": "fit", "where": "File ▸ Make Vertical Version…"}
{"id": "reframe-follow-layout", "name": "follow: layout", "summary": "Re-lays a camera clip's camera layouts, and its screen's, on the current canvas.", "page": "framing/reframe-clip", "anchor": "layout", "where": "File ▸ Make Vertical Version…"}
{"id": "reframe-follow-keep", "name": "follow: keep", "summary": "Rescales the clip from the canvas it was placed on (from_width × from_height) to the current one, as set_canvas does with rescale_clips.", "page": "framing/reframe-clip", "anchor": "keep", "where": "File ▸ Make Vertical Version…"}
{"id": "reframe-zoom", "name": "zoom", "summary": "How tight the frame is, 1 to 4, where 1 is the scale at which the picture just covers the canvas.", "page": "framing/reframe-clip", "anchor": "set-how-tight-the-frame-is"}
{"id": "reframe-ordinary-edits", "name": "Written as ordinary edits", "summary": "The framing is written as the clip's position and scale and one action per move, each of which you can change afterwards like any other.", "page": "framing/reframe-clip", "anchor": "written-as-ordinary-edits", "where": "Action lane"}
{"id": "reframe-undo", "name": "Undo Reframe Clip", "summary": "Undo takes the whole framing back in one step, Reframe Clip.", "page": "framing/reframe-clip", "anchor": "written-as-ordinary-edits", "where": "Edit ▸ Undo Reframe Clip"}
{"id": "reframe-composes-with-actions", "name": "A clip that already has actions", "summary": "A clip that already has actions keeps them: the framing is composed into them, so a zoom or pan it makes still happens inside the new framing, and a volume or speed action still does what it did.", "page": "framing/reframe-clip", "anchor": "a-clip-that-already-has-actions", "where": "File ▸ Make Vertical Version…"}
{"id": "reframe-shot-cut-in-action", "name": "A shot change inside an action", "summary": "A shot change that falls inside an action cuts it in three around the one-frame cut, so a steady change of volume still sounds exactly as it did and an eased one eases again on each side.", "page": "framing/reframe-clip", "anchor": "a-clip-that-already-has-actions"}
